window.PLAN_CHECKS=["week-1-output-0", "week-1-output-1", "week-1-output-2", "week-2-output-0", "week-2-output-1", "week-2-output-2", "week-3-output-0", "week-3-output-1", "week-3-output-2", "week-4-output-0", "week-4-output-1", "week-4-output-2", "week-5-output-0", "week-5-output-1", "week-5-output-2", "week-6-output-0", "week-6-output-1", "week-6-output-2", "week-7-output-0", "week-7-output-1", "week-7-output-2", "week-8-output-0", "week-8-output-1", "week-8-output-2", "week-9-output-0", "week-9-output-1", "week-9-output-2", "week-10-output-0", "week-10-output-1", "week-10-output-2", "week-11-output-0", "week-11-output-1", "week-11-output-2", "week-12-output-0", "week-12-output-1", "week-12-output-2", "module-robotics", "module-rl", "module-actor-critic", "module-imitation", "module-generative", "module-world-models", "module-planning", "module-uncertainty", "module-systems", "lab-bellman", "lab-geometry", "lab-ppo", "lab-sac", "lab-logging", "lab-bc", "lab-diffusion", "lab-dynamics", "lab-mpc", "lab-imagination", "lab-acquisition", "lab-evaluation", "release-0", "release-1", "release-2", "release-3", "release-4", "release-5"];
window.PLAN_SEARCH=[{"title": "The Physical AI program", "kind": "Overview", "href": "index.html", "text": "A detailed three-month program: foundational papers, Cosmos, OpenVLA, robot-learning theory, coding labs and obstruction-triggered policy adaptation. Outreach begins in week 7."}, {"title": "Weekly roadmap", "kind": "Guide", "href": "roadmap.html", "text": "01 / Weekly roadmap Twelve weeks. Clear deliverables. Six focused days each week. Separate time for theory, implementation, research and interview preparation; no double-counted hours. Your outreach boundary: private preparation during weeks 1–6. Researcher conversations, applications and follow-ups begin in week 7: . All Foundations Method Evidence Release WEEK 01 Foundations Establish the foundations and the experiment contract Understand the r"}, {"title": "Week 01: Establish the foundations and the experiment contract", "kind": "Week", "href": "week-01.html", "text": "Understand the robot-learning loop and start the research infrastructure immediately. Diagnose knowledge gaps instead of redoing material already mastered. Why does a blockage sometimes require replanning, sometimes a policy update, and sometimes a better world model?"}, {"title": "Week 02: Understand policy optimization; finish the first vertical slice", "kind": "Week", "href": "week-02.html", "text": "Implement enough RL to defend the equations and establish a repeatable task pipeline before increasing model scale. How do PPO and SAC differ, and why are imagined transitions not automatically equivalent to real off-policy data?"}, {"title": "Week 03: Build the base policy and the first predictive model", "kind": "Week", "href": "week-03.html", "text": "Get the smallest scientifically useful policy/world-model pair running. Maintain the same task across learning exercises and research. What information would a world model need to faithfully simulate your newly introduced blocker?"}, {"title": "Week 04: Make imagination useful; establish the planning baseline", "kind": "Week", "href": "week-04.html", "text": "Verify the model can support decisions and build the strongest simple alternative to policy fine-tuning. Why might a perfect-looking predicted video still be a poor training environment?"}, {"title": "Week 05: Implement the dream→update→execute loop", "kind": "Week", "href": "week-05.html", "text": "Demonstrate genuine policy parameter adaptation from imagined experience, with a fixed model during each adaptation round. Where does the policy gradient or synthetic replay signal come from when the world model is frozen?"}, {"title": "Week 06: Add real verification and freeze the research question", "kind": "Week", "href": "week-06.html", "text": "Finish the six-week preparation period with an honest pilot and a defensible experimental plan. Outreach has not started yet. Why does your method need a few real trials, and which trials should it choose?"}, {"title": "Week 07: Start outreach and run the primary comparison", "kind": "Week", "href": "week-07.html", "text": "Begin researcher conversations after six full weeks while generating the first budget-matched results. How is your experiment different from choosing the best imagined trajectory?"}, {"title": "Week 08: Test generalization and the value of active selection", "kind": "Week", "href": "week-08.html", "text": "Determine whether improvement transfers beyond the correction layouts and whether active selection actually beats random selection. What exactly is held out, and why does your split test the intended generalization?"}, {"title": "Week 09: Run targeted ablations and interrogate failure", "kind": "Week", "href": "week-09.html", "text": "Understand the mechanism and close the most consequential experimental gaps. How do you know the improvement came from your correction strategy rather than extra compute or extra data?"}, {"title": "Week 10: Write the story and package a reproducible result", "kind": "Week", "href": "week-10.html", "text": "Turn experiments into a research artifact that can be inspected, rerun and discussed in an interview. What is the single strongest result, the strongest alternative explanation, and the biggest limitation?"}, {"title": "Week 11: Close evidence gaps and rehearse deeply", "kind": "Week", "href": "week-11.html", "text": "Finish only experiments needed to substantiate the main claims, while increasing interview intensity. How would you extend this work in an industry team, and what would you deliberately avoid scaling first?"}, {"title": "Week 12: Release the artifact and complete the interview transition", "kind": "Week", "href": "week-12.html", "text": "Deliver a complete public research artifact and communicate the work with precision. What did you learn that would change how a deployed robot should use its world model?"}, {"title": "Theory and foundations", "kind": "Guide", "href": "theory.html", "text": "02 / Theory &amp; foundations Understand it well enough to use it. Build on existing modeling and research strengths. Focus new study on robotics, RL, control, learned dynamics and rigorous experiments. Study the lineage, not only the latest release. Use the foundational-paper curriculum with these modules, then compare current world models and robot policies . These readings are assigned within each week’s theory hours. Before you start / 90 min"}, {"title": "Robotics foundations", "kind": "Theory", "href": "theory-robotics.html", "text": "What connects a policy output to motion of a real end effector? Reference frames; SE(3), rotation matrices, quaternions, transform composition and camera-to-robot calibration. Forward and inverse kinematics; Jacobians, singularities, joint limits and task-space versus joint-space commands. Joint position, velocity and torque control; Cartesian impedance; where a learned policy sits above the controller. Observations, controller frequency, action duration, latency and synchronization. Review dynamics conceptually rather than spending weeks deriving every manipulator equation."}, {"title": "RL essentials and credit assignment", "kind": "Theory", "href": "theory-rl.html", "text": "What is actually optimized when a robot learns from experience? MDPs versus POMDPs; return, discount, occupancy and the difference between state and observation. Bellman expectation and optimality; Monte Carlo versus TD; bootstrapping, bias and variance. Policy gradients, baselines, advantage estimation and actor–critic methods. Exploration, replay, reward design, reward hacking, sparse success signals and termination versus time-limit truncation."}, {"title": "PPO, SAC and stable optimization", "kind": "Theory", "href": "theory-actor-critic.html", "text": "Which policy update is appropriate for continuous robot actions? PPO: rollout collection, old log-probabilities, clipped objective, value loss, entropy and advantage normalization. SAC: twin critics, target networks, replay, entropy temperature and reparameterized tanh-Gaussian actions. Why clipping is not a hard trust-region guarantee; why off-policy learning is attractive when robot samples are expensive. Exploding values, observation normalization, reward scale, update-to-data ratio and gradient/debugging diagnostics."}, {"title": "Imitation, offline RL and robot data", "kind": "Theory", "href": "theory-imitation.html", "text": "How do demonstrations become a robust starting policy? Behavior cloning; covariate shift; DAgger and corrective demonstrations. Offline RL, out-of-distribution action values, conservatism, and why arbitrary online updates can destroy a good offline policy. Episode boundaries, action normalization, camera alignment, observation history and dataset splitting by scene or episode. Chunked actions, execution horizons, observation horizons and the control trade-off between smoothness and reactivity."}, {"title": "Generative robot policies and VLAs", "kind": "Theory", "href": "theory-generative.html", "text": "What do diffusion, flow matching and a VLA change about the action distribution? Transformer attention and modality masks; DDPM denoising and conditional flow matching before robot-specific architectures. ACT and Diffusion Policy: action chunks, multimodality, execution horizons and temporal aggregation. RT-1 → RT-2 → Open X-Embodiment/Octo/OpenVLA: scaling robot data, VLM transfer and original discrete action decoding. OpenVLA-OFT and π₀/openpi: continuous action chunks, parallel decoding, flow matching, proprioception and embodiment dependence. LoRA, heads/adapters versus full fine-tuning; data, memory, inference latency and held-out execution. Survey π₀.₅ and GR00T as comparison families."}, {"title": "Learned world models and imagination", "kind": "Theory", "href": "theory-world-models.html", "text": "What must a model predict for imagined training to improve physical behavior? Dyna and World Models: interaction, learned simulation, planning and policy updates; PETS ensembles and MBPO synthetic replay. PlaNet/RSSM posterior versus prior, reconstruction/predictive losses, reward and continuation; Dreamer actor learning versus online search. DreamerV3 and TD-MPC2 as implementation routes; DINO-WM and V-JEPA 2-AC as action-conditioned visual-feature planning routes. Cosmos platform lineage and Cosmos 3; distinguish video generation, forward dynamics, inverse dynamics, reasoning and policy checkpoints. Cosmos Policy and DreamZero: actions plus predicted visual futures, direct execution versus planning, and what the papers establish about adaptation. Compounding error, rollout horizon, model exploitation and the difference between a realistic video and useful action-conditioned dynamics."}, {"title": "Planning, control and policy adaptation", "kind": "Theory", "href": "theory-planning.html", "text": "When is searching for a new action sequence enough, and when is learning worthwhile? Receding-horizon control; CEM, random shooting and MPPI at a conceptual level. Configuration-space obstacles, RRT intuition, contact modes, non-prehensile manipulation and geometric feasibility. Task/skill sequencing versus continuous action optimization; symbolic versus neural world models. Transient replanning versus persistent policy updates; retention, transfer, compute amortization and total recovery latency."}, {"title": "Uncertainty, active correction and evaluation", "kind": "Theory", "href": "theory-uncertainty.html", "text": "Which few physical trials most improve the next recovery? Epistemic versus aleatoric uncertainty; ensembles; disagreement versus calibrated uncertainty. Active learning under policy-induced distribution shift; uncertainty sampling versus expected decision improvement. Model optimism, failure discrimination, Brier score, success reliability and predicted-versus-observed outcomes. Paired comparisons, bootstrap intervals, layout-level independence, seed variation, cost accounting and negative results."}, {"title": "Research engineering and deployment", "kind": "Theory", "href": "theory-systems.html", "text": "Can someone else rerun, debug and trust your experiment? PyTorch shapes, autograd boundaries, checkpointing, evaluation mode, vectorized environments and reproducible random generators. Dataset manifests, immutable split IDs, versioned configs, model hashes and replay-buffer provenance. Training throughput, GPU memory, inference latency, parallel rollout generation and stale observations. Robot interfaces, observation/action contracts, episode logging, reset time, command limits and recovery rollback."}, {"title": "Implementation labs", "kind": "Guide", "href": "implementation.html", "text": "03 / Implementation labs Turn concepts into working code. Twelve bounded assignments. Implement the essential mechanics yourself; reproduce and modify larger systems instead of rebuilding every framework. Pretrained-model practice / Weeks 5–7 Work with a VLA and a world foundation model. The compact coding labs are complemented by two bounded practice blocks: OpenVLA/OFT or openpi inference and adaptation, plus a Cosmos/world-action-model capabil"}, {"title": "Lab 01: A blocked gridworld and Bellman backups", "kind": "Lab", "href": "lab-01.html", "text": "Make the obstruction precise before adding neural networks. Keep the start and goal fixed; change only a wall or passage. Implement deterministic transitions and value iteration with an explicit terminal state. Evaluate the original policy after adding the wall. Then recompute the policy using the updated dynamics. Plot or print the original path, blocked attempt and revised path; inspect Bellman residuals. Explain why this experiment demonstrates replanning rather than learning a missing skill."}, {"title": "Lab 02: Frames, kinematics and an IK controller", "kind": "Lab", "href": "lab-02.html", "text": "Build enough geometric intuition to debug a robot policy's actions instead of treating the controller as a black box. Implement planar two-link forward kinematics and the analytical Jacobian. Check the Jacobian against finite differences and run damped least-squares IK. Compose two homogeneous transforms and verify inverse/composition identities. Repeat the end-effector reaching example in the chosen simulator and document action units and frames."}, {"title": "Lab 03: Policy gradients, GAE and a PPO update", "kind": "Lab", "href": "lab-03.html", "text": "Own the update equations; reuse the surrounding training infrastructure. Implement discounted returns and GAE on hand-written trajectories. Implement clipped policy loss, value loss, entropy and approximate KL with explicit old log-probabilities. Read CleanRL's PPO file end to end; run one small Gymnasium task and log seeds/configs. Make one controlled intervention: remove advantage normalization or change the clipping coefficient and explain the effect."}, {"title": "Lab 04: SAC, replay and continuous actions", "kind": "Lab", "href": "lab-04.html", "text": "Use a reference SAC implementation as the continuous-control workhorse for later residual policy adaptation. Trace the actor, two critics, target critics, replay sampling and entropy-temperature update. Run a small continuous-control benchmark using the repository's documented environment. Inspect the tanh-Gaussian log-probability and action rescaling. Write one numerical comparison. Save/reload the actor and normalization state and evaluate on fixed initial states."}, {"title": "Lab 05: Robot interface and episode recorder", "kind": "Lab", "href": "lab-05.html", "text": "Create the shared interface every baseline will use. Finish a simulator episode before extensive collection. Define observe(), act(), reset() and step() with frame, units, timestamps and frequency documented. Record observations, executed actions, raw policy outputs, rewards, termination, collision/contact events and scene IDs. Save an episode manifest including calibration/configuration/checkpoint hashes and source = real, simulator or imagined. Replay the log offline; identify dropped frames, timestamp inversions and action saturation."}, {"title": "Lab 06: Behavior cloning and distribution shift", "kind": "Lab", "href": "lab-06.html", "text": "Establish what the policy can already do before you claim it improves in imagination. Collect or generate 50–100 simple demonstration trajectories in simulation; choose hardware counts only after timing resets. Train a small MLP BC policy on state observations, or a frozen visual encoder plus policy head. Split by layout/episode and evaluate closed-loop completion, not frame-level action error alone. Introduce held-out blocker placements and classify failures into perception, planning, contact/control and missing-skill cases."}, {"title": "Lab 07: A multimodal action generator", "kind": "Lab", "href": "lab-07.html", "text": "Connect your generative-modeling background to robot action distributions without spending the month training a foundation model. Create a synthetic dataset with two valid routes around an obstacle. Train a conditional denoiser or a tiny flow-matching vector field over action chunks; connect the objective to the assigned DDPM/flow reading. Compare samples against an MSE regressor whose mean may cross the obstacle. Inspect Diffusion Policy, original OpenVLA, OpenVLA-OFT and openpi action interfaces. Continue into the separately budgeted six-hour VLA practice; one actual checkpoint route is sufficient."}, {"title": "Lab 08: An action-conditioned dynamics ensemble", "kind": "Lab", "href": "lab-08.html", "text": "Start with a transparent learned dynamics model; expose its failure at the new obstruction. Fit three small models to delta-state transitions, with bootstrapped episode-level datasets. Train and evaluate on nominal and blocked transitions; preserve the training/development/test split. Compare one-step error with 5/10/20-step rollout errors and failure/success discrimination. Add a frozen visual encoder and latent dynamics if the sensor pathway and compute permit. Record this as a separate observation setting."}, {"title": "Lab 09: CEM-MPC as the essential baseline", "kind": "Lab", "href": "lab-09.html", "text": "Test whether the current learned model can solve the obstruction through search before adding policy updates. Sample bounded action sequences and score them with the learned dynamics and the same task objective used by adaptation. Refit elite action mean/variance, execute only the first action or chunk, and reobserve. Warm-start from the remaining previous plan; log model calls and wall-clock latency. Compare with random shooting and exact-physics planning as a diagnostic. Label the included 2-D point example as a teaching demo, not a robot benchmark."}, {"title": "Lab 10: Actual policy fine-tuning inside the model", "kind": "Lab", "href": "lab-10.html", "text": "Demonstrate parameter updates that persist after returning to execution; do not relabel action-sequence search as fine-tuning. Snapshot the base actor and start each adaptation comparison from the same checkpoint. Infer the current model state from recent observations. Generate short imagined rollouts from real/development anchor states. Freeze dynamics within an adaptation round. Fine-tune a residual actor using synthetic transitions and a documented SAC-style update; retain a mix of original replay for retention. Evaluate in the actual simulator or robot, then compare predicted improvement with executed improvement. Enforce an update/time budget and keep rollback available."}, {"title": "Lab 11: Choose the next few physical trials", "kind": "Lab", "href": "lab-11.html", "text": "Turn the earlier honesty project into a concrete, budget-matched correction experiment. Generate a fixed candidate pool from the current policy and legal development layouts. Define a transparent score: predicted success multiplied by outcome disagreement; use a diversity filter so top selections are not duplicates. Compare with uniform random selection from the same pool. Count selection compute and aborted real attempts. Add real transitions, update the world model between rounds, then repeat policy adaptation. Keep score weights fixed before final evaluation."}, {"title": "Lab 12: An honest evaluation report", "kind": "Lab", "href": "lab-12.html", "text": "Produce conclusions that survive a skeptical research interview. Aggregate by held-out layout and training seed; retain raw outcomes. Plot real success versus correction trials, recovery latency and total model calls. Report model optimism, success/failure discrimination and nominal-task retention together. Use layout-level paired bootstrap intervals for method differences. Declare small hardware evaluations preliminary rather than inferring significance from a few episodes."}, {"title": "Research project and experiment protocol", "kind": "Research", "href": "research.html", "text": "Detailed experiment design: task, architecture, imagined policy updates, active physical verification, baselines, budgets, data splits, metrics and decision gates."}, {"title": "Reading room and related-work boundaries", "kind": "Reading", "href": "reading.html", "text": "Paper-reading questions, evidence boundaries, world-model classifications and a novelty matrix for obstruction-triggered adaptation."}, {"title": "Interview and career preparation", "kind": "Interview", "href": "interviews.html", "text": "34 interview questions including model lineages, Cosmos, OpenVLA, coding practice and an outreach schedule beginning in week 7."}, {"title": "Resource library and implementation references", "kind": "Guide", "href": "resources.html", "text": "07 / Resource library A small stack, used deliberately. Read the theory references deeply and pin the code you actually run. Repository availability is not a guarantee of checkpoint, GPU or robot-interface compatibility. The foundational papers and reading order → Current model families and required practice → Explain and derive Spinning Up · core RL concepts ↗ https://spinningup.openai.com/en/latest/spinningup/rl_intro.html Spinning Up · policy "}, {"title": "First Results with Dyna, an Integrated Architecture for Learning, Planning and Reacting", "kind": "Paper", "href": "reading-foundations.html#paper-dyna", "text": "Core / Model-based RL / 1991. Interleave learning from interaction with planning updates using a learned model. Draw the real-data/model-data/update loop. Extend the gridworld with a learned tabular transition table and compare equal real-transition budgets."}, {"title": "World Models", "kind": "Paper", "href": "reading-foundations.html#paper-worldmodels", "text": "Core / Model-based RL / 2018. A compressed visual representation and recurrent dynamics support a compact controller; a policy can be trained in the learned dream environment. Explain why imagined policy training predates current video foundation models, and why transfer back to the actual environment must be measured."}, {"title": "Proximal Policy Optimization Algorithms", "kind": "Paper", "href": "reading-foundations.html#paper-ppo-paper", "text": "Core / Learning / 2017. Optimize a clipped policy-surrogate objective using collected trajectories and repeated minibatch updates. Derive the clipped cases for both advantage signs and connect them to the supplied PPO update. Clipping does not guarantee model fidelity."}, {"title": "Soft Actor-Critic: Off-Policy Maximum Entropy Deep Reinforcement Learning with a Stochastic Actor", "kind": "Paper", "href": "reading-foundations.html#paper-sac-paper", "text": "Core / Learning / 2018. Learn a stochastic continuous-action actor and critics with an entropy-regularized objective and replay. Trace the practical SAC variant you run. Separate changes between the original paper and a modern automatic-temperature implementation."}, {"title": "Deep Reinforcement Learning in a Handful of Trials using Probabilistic Dynamics Models", "kind": "Paper", "href": "reading-foundations.html#paper-pets", "text": "Core / Model-based RL / 2018. PETS combines probabilistic dynamics ensembles, trajectory sampling and action-sequence optimization. Justify the ensemble and MPC baseline. Ensemble spread is a diagnostic, not a calibrated guarantee against shared contact errors."}, {"title": "Learning Latent Dynamics for Planning from Pixels", "kind": "Paper", "href": "reading-foundations.html#paper-planet", "text": "Core / Model-based RL / 2018 / ICML 2019. PlaNet learns recurrent stochastic latent dynamics from images and plans within that latent space. Draw deterministic/stochastic state paths and posterior/prior inputs. Contrast latent-state inference with model-weight adaptation."}, {"title": "Dream to Control: Learning Behaviors by Latent Imagination", "kind": "Paper", "href": "reading-foundations.html#paper-dreamer-paper", "text": "Core / Model-based RL / 2019 / ICLR 2020. Dreamer learns an actor and value function through imagined latent trajectories. Contrast persistent actor updates with PlaNet's online action search. Trace which gradients pass through the model and which parameters are frozen."}, {"title": "When to Trust Your Model: Model-Based Policy Optimization", "kind": "Paper", "href": "reading-foundations.html#paper-mbpo", "text": "Core / Model-based RL / 2019. Short model-generated rollouts branch from real replay to limit the effect of model error during policy optimization. Design real/synthetic replay provenance and a rollout-horizon ablation. This is a direct foundation for the compact research loop."}, {"title": "Diffusion Policy: Visuomotor Policy Learning via Action Diffusion", "kind": "Paper", "href": "reading-foundations.html#paper-diffusion-paper", "text": "Core / Robot policies / 2023. Represent a conditional distribution over robot action sequences through denoising and execute with receding-horizon control. Implement the two-route denoiser. Distinguish diffusion steps, prediction horizon, execution horizon and the control rate."}, {"title": "OpenVLA: An Open-Source Vision-Language-Action Model", "kind": "Paper", "href": "reading-foundations.html#paper-openvla-paper", "text": "Core / Robot policies / 2024. Adapt a pretrained vision-language backbone to predict tokenized robot actions using heterogeneous robot demonstrations. Trace image/instruction preprocessing, token-to-action decoding and dataset-specific action unnormalization. Study the limits of zero-shot embodiment transfer."}, {"title": "π₀: A Vision-Language-Action Flow Model for General Robot Control", "kind": "Paper", "href": "reading-foundations.html#paper-pi0-paper", "text": "Core / Robot policies / 2024 / RSS 2025. Combine a pretrained VLM with a flow-matching action expert for continuous robot action generation. Compare OpenVLA's original action tokens with flow-based action chunks. Explain the role of language conditioning versus a predictive dynamics model."}, {"title": "Cosmos Policy: Fine-Tuning Video Models for Visuomotor Control and Planning", "kind": "Paper", "href": "reading-foundations.html#paper-cosmos-policy-paper", "text": "Core / World-action models / 2026. Post-train a video foundation model to generate robot action chunks, future states and values; predictions can support test-time planning. Trace direct-policy versus planning deployment. This is essential related work, but its planning result does not establish deployment-time RL inside imagination."}, {"title": "A Reduction of Imitation Learning and Structured Prediction to No-Regret Online Learning", "kind": "Paper", "href": "reading-foundations.html#paper-dagger", "text": "Survey / Learning / 2011. DAgger addresses the changing state distribution induced by executing a learned imitation policy through dataset aggregation. Compare expert-labeled corrections with our executed transition feedback. Access to an expert is an additional assumption."}, {"title": "Attention Is All You Need", "kind": "Paper", "href": "reading-foundations.html#paper-attention", "text": "Survey / Building blocks / 2017. Attention-based sequence modeling supplies the basic transformer operations reused in modern multimodal models. Write a masked attention layer, annotate query/key/value dimensions, and explain temporal and modality masks. Upgrade to deep study if this is unfamiliar."}, {"title": "Auto-Encoding Variational Bayes", "kind": "Paper", "href": "reading-foundations.html#paper-vae", "text": "Survey / Building blocks / 2013 / ICLR 2014. Variational inference and reparameterized latent variables provide a foundation for learned stochastic representations. Derive reconstruction and KL terms; explain why image reconstruction alone need not preserve contact-relevant state."}, {"title": "Denoising Diffusion Probabilistic Models", "kind": "Paper", "href": "reading-foundations.html#paper-ddpm", "text": "Survey / Building blocks / 2020. Learn a reverse denoising process from a forward noise-corruption construction. Write the noise-prediction objective used by the small action generator. Separate a generative model from a decision objective."}, {"title": "Flow Matching for Generative Modeling", "kind": "Paper", "href": "reading-foundations.html#paper-flow", "text": "Survey / Building blocks / 2022 / ICLR 2023. Train a vector field along probability paths to construct a continuous generative process. Derive the straight-line conditional target used in the mini-lab and compare its inference procedure with iterative denoising."}, {"title": "LoRA: Low-Rank Adaptation of Large Language Models", "kind": "Paper", "href": "reading-foundations.html#paper-lora", "text": "Survey / Building blocks / 2021 / ICLR 2022. Freeze pretrained weights and learn low-rank parameter updates. Implement W + BA, verify trainable-parameter counts, and distinguish reduced training memory from inference latency or robot sample efficiency."}, {"title": "RT-1: Robotics Transformer for Real-World Control at Scale", "kind": "Paper", "href": "reading-foundations.html#paper-rt1", "text": "Survey / Robot policies / 2022. A transformer policy learns language-conditioned robot control from a large real-robot task dataset. Explain how scalable robot policy learning precedes modern VLM-based VLAs. Inspect the observation and action tokenization."}, {"title": "RT-2: Vision-Language-Action Models Transfer Web Knowledge to Robotic Control", "kind": "Paper", "href": "reading-foundations.html#paper-rt2", "text": "Survey / Robot policies / 2023. Co-fine-tune vision-language models on web and robot data, representing actions as tokens. Explain semantic transfer versus physical dynamics learning. A correct instruction interpretation does not establish obstacle recovery."}, {"title": "Open X-Embodiment: Robotic Learning Datasets and RT-X Models", "kind": "Paper", "href": "reading-foundations.html#paper-oxe", "text": "Survey / Robot policies / 2023. Standardize heterogeneous robot datasets and investigate cross-embodiment policy transfer. Audit action conventions, observation keys, mixture weights and embodiment coverage before using a generalist checkpoint."}, {"title": "Learning Fine-Grained Bimanual Manipulation with Low-Cost Hardware", "kind": "Paper", "href": "reading-foundations.html#paper-act", "text": "Survey / Robot policies / 2023. The ALOHA work introduces Action Chunking with Transformers for imitation learning on low-cost bimanual hardware. Compare chunking and temporal aggregation with single-step BC; useful context for a practical low-cost-arm artifact."}, {"title": "Octo: An Open-Source Generalist Robot Policy", "kind": "Paper", "href": "reading-foundations.html#paper-octo", "text": "Survey / Robot policies / 2024. An open generalist transformer policy supports adaptation across robot observations and action spaces. Compare its interfaces and diffusion action head with original OpenVLA and π₀. These policies do not automatically expose forward dynamics."}, {"title": "Fine-Tuning Vision-Language-Action Models: Optimizing Speed and Success", "kind": "Paper", "href": "reading-foundations.html#paper-oft", "text": "Survey / Robot policies / 2025. OpenVLA-OFT studies parallel decoding, chunking, continuous actions and fine-tuning objectives. Separate the original OpenVLA implementation from OFT. Compare actual observation inputs and measured closed-loop latency, not model names alone."}, {"title": "Mastering Diverse Domains through World Models", "kind": "Paper", "href": "reading-foundations.html#paper-dreamerv3", "text": "Survey / Model-based RL / 2023 preprint. DreamerV3 develops a broadly applicable world-model agent and robust training recipe across domains. Inspect the current implementation after understanding Dreamer. Pin the version rather than assuming all Dreamer generations share the same losses."}, {"title": "TD-MPC2: Scalable, Robust World Models for Continuous Control", "kind": "Paper", "href": "reading-foundations.html#paper-tdmpc-paper", "text": "Survey / Model-based RL / 2023 / ICLR 2024. Use a task-oriented latent world model, learned values and online planning for continuous control. Explain why decision-relevant models need not reconstruct images. Use it to defend a strong planning comparison."}, {"title": "DINO-WM: World Models on Pre-trained Visual Features enable Zero-shot Planning", "kind": "Paper", "href": "reading-foundations.html#paper-dinowm-paper", "text": "Survey / Visual world models / 2024. Learn action-conditioned transitions over pretrained visual features for planning. Identify what the frozen visual representation supplies and what robot interaction data still teaches. Feature prediction can miss contact details."}, {"title": "V-JEPA 2: Self-Supervised Video Models Enable Understanding, Prediction and Planning", "kind": "Paper", "href": "reading-foundations.html#paper-vjepa2", "text": "Survey / Visual world models / 2025. Video representation learning is followed by an action-conditioned model for robotic planning. Distinguish video pretraining from V-JEPA 2-AC robot post-training and planning. Avoid treating an action-free encoder as a robot simulator."}, {"title": "Cosmos World Foundation Model Platform for Physical AI", "kind": "Paper", "href": "reading-foundations.html#paper-cosmos1", "text": "Survey / World-action models / 2025. A world foundation model platform combines video modeling, data processing and downstream customization for Physical AI. Read for the original platform motivation, then consult current model cards. The historical release is not the current implementation target."}, {"title": "Cosmos 3: Omnimodal World Models for Physical AI", "kind": "Paper", "href": "reading-foundations.html#paper-cosmos3", "text": "Survey / World-action models / 2026. A shared omnimodal architecture includes world generation, reasoning and action-related capabilities. Identify the exact checkpoint and interface for forward dynamics, inverse dynamics or policy use. A generic video quickstart is not the action-conditioned research integration."}, {"title": "World Action Models are Zero-shot Policies", "kind": "Paper", "href": "reading-foundations.html#paper-dreamzero-paper", "text": "Survey / World-action models / 2026. DreamZero jointly models future video and robot actions using a pretrained video backbone. Compare its action/video factorization with Cosmos Policy. Study embodiment assumptions and runtime before choosing it for online adaptation."}, {"title": "DINOv2: Learning Robust Visual Features without Supervision", "kind": "Paper", "href": "reading-foundations.html#paper-dinov2", "text": "Reference / Building blocks / 2023. Self-supervised image pretraining produces reusable visual features. Inspect patch features for a scene containing a blocker; strong visual features do not by themselves specify action-conditioned transitions."}, {"title": "Conservative Q-Learning for Offline Reinforcement Learning", "kind": "Paper", "href": "reading-foundations.html#paper-cql", "text": "Reference / Learning / 2020. Regularize offline value learning to address overestimation on unsupported actions. Explain why an actor can exploit optimistic critics even with an accurate-looking world model."}, {"title": "Offline Reinforcement Learning with Implicit Q-Learning", "kind": "Paper", "href": "reading-foundations.html#paper-iql", "text": "Reference / Learning / 2021 / ICLR 2022. Learn from offline data using expectile value estimation and advantage-weighted policy extraction. Contrast offline initialization with online or imagined adaptation; a synthetic replay buffer changes the data assumptions."}, {"title": "Mastering Atari, Go, Chess and Shogi by Planning with a Learned Model", "kind": "Paper", "href": "reading-foundations.html#paper-muzero", "text": "Reference / Model-based RL / 2019 / Nature 2020. Learn the reward, value and policy quantities needed for tree search without reconstructing every observation. Use this as a conceptual counterexample to equating world modeling with photorealistic video; it is not a drop-in manipulation baseline."}, {"title": "π₀.₅: a Vision-Language-Action Model with Open-World Generalization", "kind": "Paper", "href": "reading-foundations.html#paper-pi05", "text": "Reference / Robot policies / 2025. Extend the π₀ line with heterogeneous co-training for broader generalization. Discuss what unseen-environment evaluation actually establishes and how it differs from obstacle-triggered online fine-tuning."}, {"title": "GR00T N1: An Open Foundation Model for Generalist Humanoid Robots", "kind": "Paper", "href": "reading-foundations.html#paper-gr00t", "text": "Reference / Robot policies / 2025. Couple vision-language reasoning with a diffusion-based action generator for humanoid manipulation. Compare data mixture and embodiment assumptions with OpenVLA/openpi. Read newer checkpoint documentation only when implementing that family."}, {"title": "Foundational papers and weekly reading order", "kind": "Foundations", "href": "reading-foundations.html", "text": "Dyna, World Models, PPO, SAC, PETS, PlaNet, Dreamer, MBPO, Diffusion Policy, OpenVLA, pi0, Cosmos Policy, foundational transformers and modern world-model lineages."}, {"title": "World models, VLAs and foundation-model practice", "kind": "Models", "href": "model-landscape.html", "text": "Cosmos 3, Cosmos Policy, OpenVLA, OpenVLA-OFT, openpi pi0, DreamZero, V-JEPA 2, DINO-WM, Dreamer and two bounded implementation blocks."}];
